fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // Requires that the input array is not empty and min_val is less than or equal to max_val
    // Ensures that the output vector has the same length as the input array
    // Ensures that each element in the output vector is within the range [min_val, max_val]
    // Decreases clause is not necessary here as there is no recursive call or loop that needs it
    // Invariant: The output vector is constructed based on the input array and the specified min and max values
    // The output vector will contain elements that are clipped to the specified range

    assert!(arr.len() > 0); // Assert that the input array is not empty
    assert!(min_val <= max_val); // Assert that min_val is less than or equal to max_val

    if min_val <= max_val {
        let result: Vec<i8> = arr.iter()
            .map(|&x| {
                // Each element x is checked against min_val and max_val
                if x < min_val {
                    min_val // Clip to min_val if x is less than min_val
                } else if x > max_val {
                    max_val // Clip to max_val if x is greater than max_val
                } else {
                    x // Keep x if it is within the range
                }
            })
            .collect();

        // Ensure that the result has the same length as the input array
        assert!(result.len() == arr.len());

        // Ensure that all elements in the result are within the specified range
        for &value in &result {
            assert!(value >= min_val && value <= max_val);
        }

        result // Return the clipped result
    } else {
        // If min_val is greater than max_val, return a vector filled with max_val
        let result = vec![max_val; arr.len()];

        // Ensure that the result has the same length as the input array
        assert!(result.len() == arr.len());

        // Ensure that all elements in the result are equal to max_val
        for &value in &result {
            assert!(value == max_val);
        }

        result // Return the result filled with max_val
    }
}